// Cursor glow over a subtle gradient — Shadertoy style.
// iMouse is read in pixels (Shadertoy convention); values in 0..1 are treated as uv.
// With no mouse input (0,0), the glow drifts on a slow Lissajous path so renders stay alive.
uniform float uRadius;     // @param 0.22 0.02 1.0
uniform float uIntensity;  // @param 1.0 0 3
uniform float uFalloff;    // @param 2.2 0.5 6
uniform float uDrift;      // @param 0.25 0 2
uniform vec3  uGlow;       // @param #FF8A3D
uniform vec3  uTop;        // @param #141826
uniform vec3  uBottom;     // @param #07080D
uniform bool  uFollowMouse; // @param true

void main() {
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 asp = vec2(aspect, 1.0);

  // Subtle diagonal gradient with soft noise breathing and dithering against banding.
  float g = clamp(uv.y * 0.85 + uv.x * 0.15, 0.0, 1.0);
  vec3 col = mix(uBottom, uTop, smoothstep(0.0, 1.0, g));
  col += 0.015 * (fbm(uv * 3.0 * asp + iTime * 0.05) - 0.5);

  // Cursor position in uv space.
  vec2 m = iMouse;
  bool hasMouse = uFollowMouse && (m.x > 0.0 || m.y > 0.0);
  if (hasMouse && (m.x > 1.0 || m.y > 1.0)) m /= max(iResolution, vec2(1.0));
  float t = iTime * uDrift;
  vec2 drift = vec2(0.5 + 0.28 * sin(t * 1.3), 0.5 + 0.22 * sin(t * 1.9 + 1.2));
  vec2 c = hasMouse ? m : drift;

  // Glow: soft core + wide halo, aspect-correct.
  float d = length((uv - c) * asp);
  float r = max(uRadius, 1e-3);
  float halo = 1.0 / (1.0 + pow(d / r, uFalloff) * 4.0);
  float core = exp(-pow(d / (r * 0.18), 2.0));
  float pulse = 0.94 + 0.06 * sin(iTime * 2.0);

  vec3 glow = uGlow * halo * 0.85 + mix(uGlow, vec3(1.0), 0.6) * core * 0.6;
  col += glow * uIntensity * pulse;

  // Gentle vignette + tonemap + dither.
  vec2 q = (uv - 0.5) * asp;
  col *= 1.0 - 0.35 * dot(q, q);
  col = col / (1.0 + col * 0.35);
  col += (hash(uv * iResolution + fract(iTime)) - 0.5) / 255.0;

  fragColor = vec4(col, 1.0);
}
